import React, { useState, useEffect } from 'react';
import './Categories.css';

const Categories = () => {
  const [categories, setCategories] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Kategóriák betöltése
  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await fetch('http://localhost:5123/Card'); // Backend API endpoint
        if (!response.ok) {
          throw new Error('Hiba történt a kategóriák betöltésekor.');
        }
        const data = await response.json();
        const uniqueCategories = [...new Set(data.products.map((product) => product.Category))];
        setCategories(uniqueCategories);
      } catch (err) {
        setError(err.message);
      }
    };

    fetchCategories();
  }, []);

  // Termékek betöltése a kiválasztott kategóriához
  const handleCategoryClick = async (category) => {
    setSelectedCategory(category);
    setLoading(true);
    setError('');
    try {
      const response = await fetch(`http://localhost:5123/Card/category/${category}`); // Backend API endpoint
      if (!response.ok) {
        throw new Error('Hiba történt a termékek betöltésekor.');
      }
      const data = await response.json();
      setProducts(data.products);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="categories-container">
      <h2>Kategóriák</h2>
      {error && <p className="error-message">{error}</p>}
      <div className="category-buttons">
        {categories.map((category, index) => (
          <div
            key={index}
            className={`category-button ${selectedCategory === category ? 'selected' : ''}`}
            onClick={() => handleCategoryClick(category)}
          >
            <span>{category}</span>
          </div>
        ))}
      </div>
      <div className="products-list">
        {loading ? (
          <p>Betöltés...</p>
        ) : (
          products.map((product) => (
            <div key={product.id} className="product-item">
              <img src={product.image} alt={product.name} />
              <h3>{product.name}</h3>
              <p>{product.description}</p>
              <p>Ár: {product.price} Ft</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Categories;
